const mongoose = require("mongoose");
const { Schema } = mongoose;

/* ------------------ Image ------------------ */
// Mirrors the image shape used in models/products.js
const imageSchema = new Schema(
    {
        url: { type: String, required: true },
        is_primary: { type: Boolean, default: false },
    },
    { _id: true }
);

/* ------------------ Bundle Member ------------------ */
// A member is one of the vendor's own products (optionally a specific variant),
// with a quantity. Same-vendor is enforced in the service layer at write time.
const bundleMemberSchema = new Schema(
    {
        product_id: { type: Schema.Types.ObjectId, ref: "Product", required: true },
        // Null = use the product's base/first variant (resolved via buildVariantSnapshot).
        variant_id: { type: Schema.Types.ObjectId, default: null },
        quantity: { type: Number, default: 1, min: 1 },
    },
    { _id: true }
);

/* ------------------ Bundle Schema ------------------ */
const bundleSchema = new Schema(
    {
        vendor_id: {
            type: Schema.Types.ObjectId,
            ref: "Seller",
            required: [true, 'Please select a vendor for this bundle.'],
            index: true,
        },

        // Localized content — at least one full language set is required when published.
        title_en: { type: String, trim: true },
        title_ar: { type: String, trim: true },

        subtitle_en: { type: String, trim: true },
        subtitle_ar: { type: String, trim: true },

        description_en: { type: String },
        description_ar: { type: String },

        // Slugs — sparse unique, generated by the service (generateBundleSlug).
        slug_en: { type: String, trim: true, sparse: true, unique: true },
        slug_ar: { type: String, trim: true, sparse: true, unique: true },

        images: [imageSchema],

        // The products that make up this bundle (validate >= 2 below).
        members: [bundleMemberSchema],

        // Pricing — the effective bundle price is ALWAYS recomputed from members'
        // current effective prices; it is never persisted as a source of truth.
        //   fixed   -> pricing_value is the total price for the whole set
        //   percent -> pricing_value is % off the members' combined price (0-100)
        //   amount  -> pricing_value is a flat amount off the combined price
        pricing_mode: {
            type: String,
            enum: ['fixed', 'percent', 'amount'],
            default: 'fixed',
        },
        pricing_value: { type: Number, default: 0, min: 0 },

        status: { type: String, enum: ['draft', 'pending', 'published'], default: 'draft' },

        // True once admin-approved (published). Sticky — resetting to draft does not clear it.
        is_published: { type: Boolean, default: false },

        // Active (visible on marketplace)? Set false when vendor is suspended.
        is_active: { type: Boolean, default: true },

        // Subscription lifecycle bookkeeping (parity with products).
        subscription_hidden_at: { type: Date, default: null },
        modified_after_subscription_restore: { type: Boolean, default: false },

        sold_count: { type: Number, default: 0 },

        created_at: { type: Date, default: Date.now },
    },
    {
        timestamps: false,
    }
);

/* ------------------ Validation Middleware ------------------ */
bundleSchema.pre('validate', function (next) {
    // Rule 1: a published bundle needs a complete language set in EN or AR.
    if (this.status === 'published') {
        const hasEnglishSet =
            !!(this.title_en?.trim() &&
                this.subtitle_en?.trim() &&
                this.description_en?.trim() &&
                this.slug_en?.trim());

        const hasArabicSet =
            !!(this.title_ar?.trim() &&
                this.subtitle_ar?.trim() &&
                this.description_ar?.trim() &&
                this.slug_ar?.trim());

        if (!hasEnglishSet && !hasArabicSet) {
            this.invalidate(
                'title_en',
                'A published bundle must have title, subtitle, description, and slug all completed in at least one language (English or Arabic).'
            );
        }
    }

    // Rule 2: a bundle must contain at least two members.
    if (!this.members || this.members.length < 2) {
        this.invalidate('members', 'A bundle must contain at least two products.');
    }

    // Rule 3: pricing_value bounds by mode.
    if (this.pricing_mode === 'percent' && (this.pricing_value < 0 || this.pricing_value > 100)) {
        this.invalidate('pricing_value', 'Percentage discount must be between 0 and 100.');
    }
    if (this.pricing_value < 0) {
        this.invalidate('pricing_value', 'Pricing value cannot be negative.');
    }

    if (typeof next === 'function') next();
});

/* ------------------ Indexing ------------------ */
bundleSchema.index({
    title_en: "text",
    title_ar: "text",
    subtitle_en: "text",
    subtitle_ar: "text",
});
bundleSchema.index({ vendor_id: 1, status: 1 });

const Bundle = mongoose.model("Bundle", bundleSchema);

module.exports = { Bundle };
